import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    void execute() {
        InputReader in = new InputReader(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        final int MOD = 998244353;
        int N = in.nextInt();
        int K = in.nextInt();
        int[] base = new int[10];
        for (int i = 0; i < K; i++) {
            base[in.nextInt()] = 1;
        }

        int[] result = new int[]{1};
        int exp = N / 2;
        while (true) {
            if ((exp & 1) == 1) {
                result = convolve(result, base, MOD);
            }
            exp >>= 1;
            if (exp == 0) break;
            base = convolve(base, base, MOD);
        }

        long sum = 0;
        for (int val : result) {
            sum = (sum + (long)val * val) % MOD;
        }
        pw.println(sum);
        pw.close();
    }

    int[] convolve(int[] x, int[] y, int mod) {
        int len = x.length + y.length - 1;
        int size = Math.max(2, Integer.highestOneBit(len - 1) << 1);

        double[] xr = new double[size];
        double[] xi = new double[size];
        for (int i = 0; i < x.length; i++) {
            long v = ((x[i] % mod) + mod) % mod;
            xr[i] = v & 0x7FFF;
            xi[i] = v >>> 15;
        }
        fft(xr, xi, false);

        double[] yr = new double[size];
        double[] yi = new double[size];
        for (int i = 0; i < y.length; i++) {
            long v = ((y[i] % mod) + mod) % mod;
            yr[i] = v & 0x7FFF;
            yi[i] = v >>> 15;
        }
        fft(yr, yi, false);

        double[] resR = new double[size];
        double[] resI = new double[size];
        double[] tmpR = new double[size];
        double[] tmpI = new double[size];

        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double a1r = (xr[i] + xr[j]) * 0.5;
            double a1i = (xi[i] - xi[j]) * 0.5;
            double a2r = (xi[i] + xi[j]) * 0.5;
            double a2i = (xr[j] - xr[i]) * 0.5;

            double b1r = (yr[i] + yr[j]) * 0.5;
            double b1i = (yi[i] - yi[j]) * 0.5;
            double b2r = (yi[i] + yi[j]) * 0.5;
            double b2i = (yr[j] - yr[i]) * 0.5;

            resR[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resI[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            tmpR[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            tmpI[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        fft(resR, resI, true);
        fft(tmpR, tmpI, true);

        int[] out = new int[len];
        for (int i = 0; i < len; i++) {
            long a = Math.round(resR[i]);
            long b = Math.round(tmpR[i]);
            long c = Math.round(resI[i]);
            out[i] = (int)((a + ((b % mod) << 15) + ((c % mod) << 30)) % mod);
        }
        return out;
    }

    void fft(double[] re, double[] im, boolean inv) {
        int n = re.length;
        int bits = 32 - Integer.numberOfTrailingZeros(n);
        int[] rev = new int[n];
        for (int i = 1; i < n; i++) {
            rev[i] = (rev[i >> 1] >> 1) | ((i & 1) << (bits - 1));
        }
        for (int i = 1; i < n; i++) {
            if (i < rev[i]) {
                double t = re[i]; re[i] = re[rev[i]]; re[rev[i]] = t;
                double t2 = im[i]; im[i] = im[rev[i]]; im[rev[i]] = t2;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cos = new double[half];
            double[] sin = new double[half];
            double sign = inv ? -1 : 1;
            for (int i = 0; i < half; i++) {
                double angle = 2 * Math.PI * i / len * sign;
                cos[i] = Math.cos(angle);
                sin[i] = Math.sin(angle);
            }

            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double wR = cos[j];
                    double wI = sin[j];
                    double uR = re[i + j];
                    double uI = im[i + j];
                    double vR = re[i + j + half] * wR - im[i + j + half] * wI;
                    double vI = re[i + j + half] * wI + im[i + j + half] * wR;

                    re[i + j] = uR + vR;
                    im[i + j] = uI + vI;
                    re[i + j + half] = uR - vR;
                    im[i + j + half] = uI - vI;
                }
            }
        }

        if (inv) {
            for (int i = 0; i < n; i++) {
                re[i] /= n;
                im[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream in;
        private final byte[] buf = new byte[1024];
        private int p, len;

        public InputReader(InputStream in) {
            this.in = in;
        }

        private int next() {
            if (len == -1) throw new RuntimeException();
            if (p >= len) {
                p = 0;
                try { len = in.read(buf); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buf[p++] & 0xFF;
        }

        public int nextInt() {
            int c = next();
            while (c <= 32) c = next();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = next(); }
            int val = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                val = val * 10 + c - '0';
                c = next();
            } while (c > 32);
            return val * sgn;
        }
    }
}
